\begin{tikzpicture}[font=\boldmath]\small

\def\sc{2} %scale
\def\lengthA{{\sc*sqrt(3)}} %magnitude of a
\def\lengthB{{\sc*sqrt(6)}} %magnitude of b
\def\angI{0} %direction of vector a
\def\angII{90} %direction of vector b

% Defining polar points
\coordinate (a) at (0,0);
\path (a)--++(\angI:\lengthA) coordinate (b);
\path (b)--++(\angII:\lengthB) coordinate (c);

%triangle
\tkzMarkRightAngle[thick, fill=none, color=deepskyblue, size=0.5](a,b,c)

%segment labels
\draw[very thick, black,   arrows={-latex}]  (a) -- (b) node[midway,below right]{ $\mathbf{a}$};
\draw[->, very thick, black,   arrows={-latex}]  (b) -- (c) node[midway,above right]{$\mathbf{b}$};
\draw[very thick, orangepeel,   arrows={-latex}]  (a) -- (c) node[sloped,midway,above]{ $\mathbf{a+b}$};

